class Solution:
    def firstStableIndex(self, nums: list[int], k: int) -> int:
        preMax = float('-inf')
        sufMin = float('inf')
        precompute_values = [0 for _ in range(len(nums))]
        firstIndex = -1
        
        i = 0
        j = len(nums)-1
        
        while i <= len(nums)-1:
            if nums[i] > preMax:
                preMax= nums[i]
                
            if nums[j]< sufMin:
                sufMin = nums[j]
                
            # Setup a dictionary
            
            precompute_values[i] = preMax + precompute_values[i]
            precompute_values[j] = precompute_values[j]-sufMin
            
            i = i+1
            j = j-1
            
        print(precompute_values)
        
        # Now, get the first stable number
        
        for i in range(len(precompute_values)):
            if precompute_values[i] <= k:
                firstIndex = i
                break;
            
        return firstIndex
            

def evaluate(fn,expected_result, *args):
    res = fn(*args)
    
    if res != expected_result:
        print(f"Run Failed. Expected {expected_result} but got {res}")
    else:
        print("Sucessful run")

            
